class Calc {
    static int value = 10;
    static int run() {
        try {
            value += 1;
            return value;
        } finally {
            value += 10;
            System.out.print("F" + value + ":");
        }
    }
}
public class Main {
    public static void main(String[] args) {
        int r = Calc.run();
        System.out.print(r + ":" + Calc.value);
    }
}

