    private final String id;
    R(String id) { this.id = id; System.out.print("+" + id); }
    public void close() { System.out.print("-" + id); }
}
public class Main {
    public static void main(String[] args) {
        try (R first = new R("A");
             R second = new R("K")) {
            System.out.print("T");
        }
        System.out.print("E");
    }
}

